A = {0,2,4,5}
B = {1,3,6,7}
edges = []
for a in A:
    for b in B:
        u,v = min(a,b), max(a,b)
        edges.append((u,v))
edges.sort()
print(edges)
print("(0,6) in edges:", (0,6) in edges)
print("(2,6) in edges:", (2,6) in edges)

# Verify triangle-free
adj = {i:set() for i in range(8)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)
for u in range(8):
    for v in adj[u]:
        if len(adj[u] & adj[v])>0:
            print("Triangle!", u, v, adj[u]&adj[v])
            break
    else: continue
    break
else:
    print("Triangle-free OK")

# Verify maximal: every non-edge addition creates triangle
for u in range(8):
    for v in range(u+1,8):
        if (u,v) not in edges:
            if len(adj[u] & adj[v])==0:
                print("NOT maximal:",u,v)
print("Maximal check done")
